// GENERATED by /protoflow-prototype — edit the docs, not this file.
// Shape reference for prototype/app.js (regenerated on every run). Not copied into engagements.
// The product chrome every customer-facing screen shares — see .claude/references/prototype-ui.md "App chrome".
//   BRAND   ← product-name DECISION / grounding, else the humanized project id
//   NAV     ← confirmed Feature-scope items a customer sees, Feature-scope order; specced → entry SCR, not yet specced → soon
//   PERSONAS← one seeded user per actor/role in the use cases (+ guest when the product has public pages)
//   STRINGS ← only when a REQ asks for several languages; otherwise drop t() and write the copy inline
//   Build chrome with the ui.js kit (icon, iconBtn, btn, footer…); export one-line-commented helpers — the brief lists them.
import { icon, iconBtn, btn, footer } from "./ui.js";

const BRAND = { name: "Acme Booking", mark: ["Acme", "Booking"] };     // wordmark: second part in --brand color
const NAV = [
  { key: "book", label: "Book a room", screen: "SCR-001" },
  { key: "mine", label: "My bookings", screen: "SCR-003", signedIn: true },
  { key: "reports", label: "Reports", soon: true },                     // confirmed feature, not specced yet → "coming soon"
];
const PERSONAS = [                                                      // ids must exist in seed.sql
  { id: "guest", label: "Guest (not signed in)" },
  { id: "u-anna", label: "Anna — customer" },
  { id: "u-ben", label: "Ben — approver", staff: true },
];
const HOME = { guest: "SCR-001", signedIn: "SCR-003", staff: "SCR-002" };

const store = {
  get(k, d) { try { return localStorage.getItem(k) ?? d; } catch { return d; } },
  set(k, v) { try { localStorage.setItem(k, v); } catch {} },
};

export const persona = () => PERSONAS.find(p => p.id === store.get("proto.persona", "guest")) ?? PERSONAS[0];
export const signedIn = () => persona().id !== "guest";
export const homeScreen = () => (persona().staff ? HOME.staff : signedIn() ? HOME.signedIn : HOME.guest);

// Customer-facing labels for enum codes — never print raw codes (prototype-ui.md "Copy and formatting").
const LABELS = { hold: ["On hold", "warn"], approved: ["Approved", "ok"], rejected: ["Rejected", "bad"] };
export const label = code => (LABELS[code] ?? [String(code ?? "—").replace(/_/g, " ").toLowerCase().replace(/^./, c => c.toUpperCase())])[0];
export const badge = (h, code) => h("span", { class: `badge ${(LABELS[code] ?? [])[1] ?? ""}` }, label(code));
export const fmtDate = iso => (iso ? new Date(iso).toLocaleDateString(undefined, { day: "numeric", month: "short", year: "numeric" }) : "—");

// "View as" lives in the review panel (#devExtra), never in the product nav.
function personaSwitcher(ctx) {
  const box = document.getElementById("devExtra");
  if (!box || box.querySelector("select")) return;
  const sel = ctx.h("select", { style: "font-size:12px;padding:4px 6px;margin-top:6px",
    onchange: e => { store.set("proto.persona", e.target.value); ctx.go(homeScreen()); } },
    PERSONAS.map(p => ctx.h("option", { value: p.id }, p.label)));
  sel.value = persona().id;
  box.append(ctx.h("label", { class: "tog", style: "display:block" }, "View as", sel));
}

// The product navigation bar — first element of every customer-facing screen.
export function appNav(ctx, active = "") {
  const { h, go, toast } = ctx;
  personaSwitcher(ctx);
  const items = NAV.filter(n => !n.signedIn || signedIn());
  return h("header", { class: "app-nav" },
    h("a", { href: "#", class: "logo", onclick: e => { e.preventDefault(); go(homeScreen()); } }, BRAND.mark[0], h("b", {}, BRAND.mark[1])),
    items.map(n => h("a", { href: "#", class: "link" + (n.key === active ? " on" : ""),
      onclick: e => { e.preventDefault(); n.soon ? toast(`${n.label} — coming soon.`) : go(n.screen); } }, n.label)),
    h("div", { class: "grow" }),
    signedIn()
      ? h("span", { class: "link" }, persona().label.split(" ")[0])
      : h("button", { class: "btn primary", onclick: () => toast("Sign-in — coming soon.") }, "Sign in"));
}

// Site footer — last element of every customer-facing screen (ui.js footer builder; links show "coming soon").
export function appFooter(ctx) {
  return footer({ brand: BRAND.name, columns: [["Help", ["Contact us", "FAQ"]], ["Company", ["About", "Careers"]]],
    note: `© ${new Date().getFullYear()} ${BRAND.name}`, onlink: l => ctx.toast(`${l} — coming soon.`) });
}

// Guard for signed-in-only screens: redirect like the real product would. Usage: if (requireSignIn(ctx)) return;
export function requireSignIn(ctx) {
  if (signedIn()) return false;
  ctx.go(HOME.guest);
  return true;
}

// ---- Cross-screen openers: an overlay screen (drawer, modal, toast) that other screens open lives in its own module and
// exports an opener; app.js re-exports it lazily so screens stay independent. `--brief` turns each of these lines into a
// contract ("SCR-004 must export function open(ctx, booking)") for the agent writing that screen.
// Open the cancel-booking dialog (SCR-004); resolves true when cancelled.
export const openCancel = async (ctx, booking) => (await import("./booking-request/SCR-004.js")).open(ctx, booking);

// Host page for overlay screens opened by URL: what sits behind the overlay (usually the entry page's content).
export function hostPage(ctx) {
  ctx.add(appNav(ctx, "book"), ctx.h("div", { class: "page-head" }, ctx.h("h1", {}, "Book a room")), appFooter(ctx));
}
